import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Linked list in arrays: node 0 is the sentinel, nodes 1..n hold the values.
        long[] val = new long[n + 1];
        int[] next = new int[n + 1];
        for (int i = 1; i <= n; i++) val[i] = nextLong();
        for (int i = 0; i <= n; i++) next[i] = i < n ? i + 1 : -1;
        int prev = 0;
        while (next[prev] != -1) {
            int cur = next[prev];
            if (val[cur] % 2 == 0) next[prev] = next[cur]; // unlink the even node
            else prev = cur;
        }
        StringBuilder line = new StringBuilder();
        int count = 0;
        for (int cur = next[0]; cur != -1; cur = next[cur]) {
            if (count++ > 0) line.append(' ');
            line.append(val[cur]);
        }
        System.out.print(count + "\n" + line + "\n");
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// Linked list in arrays: node 0 is the sentinel, nodes 1..n hold the values.
	val := make([]int64, n+1)
	next := make([]int, n+1)
	for i := 1; i <= n; i++ {
		val[i] = nextInt()
	}
	for i := 0; i <= n; i++ {
		next[i] = i + 1
	}
	next[n] = -1
	prev := 0
	for next[prev] != -1 {
		cur := next[prev]
		if val[cur]%2 == 0 {
			next[prev] = next[cur] // unlink the even node
		} else {
			prev = cur
		}
	}
	var line []byte
	count := 0
	for cur := next[0]; cur != -1; cur = next[cur] {
		if count > 0 {
			line = append(line, ' ')
		}
		count++
		line = strconv.AppendInt(line, val[cur], 10)
	}
	out := strconv.AppendInt(nil, int64(count), 10)
	out = append(out, '\n')
	out = append(out, line...)
	out = append(out, '\n')
	os.Stdout.Write(out)
}
